      {
        "id": "lem-negative-half-reversal-preserves-integral-and-crystal-lattices",
        "kind": "lemma",
        "title": "Reversal preserves the negative-half integral and crystal lattices",
        "deps": [
          "lem-crystal-lattice-polarizations-are-perfect-at-q-zero",
