      {
        "id": "lem-string-ideal-triples-are-balanced",
        "kind": "lemma",
        "title": "The string-ideal triples are balanced: the induction step (Kashiwara 7.4.1 / JKK 10.4)",
        "deps": [
          "def-axiom-of-choice",
